create policy sync_entities_insert on public.sync_entities for insert to authenticated with check (updated_by=(select auth.uid()) and (public.iberfit_role()='admin'::public.iberfit_role or (client_id is not null and public.is_assigned_coach(client_id)) or client_id=(select public.iberfit_client_id())));
create policy sync_entities_update on public.sync_entities for update to authenticated using (public.iberfit_role()='admin'::public.iberfit_role or (client_id is not null and public.is_assigned_coach(client_id)) or client_id=(select public.iberfit_client_id())) with check (updated_by=(select auth.uid()) and (public.iberfit_role()='admin'::public.iberfit_role or (client_id is not null and public.is_assigned_coach(client_id)) or client_id=(select public.iberfit_client_id())));
create policy sync_events_insert on public.sync_events for insert to authenticated with check (actor_user_id=(select auth.uid()) and (public.iberfit_role()='admin'::public.iberfit_role or (client_id is not null and public.is_assigned_coach(client_id)) or client_id=(select public.iberfit_client_id())));
create policy outbox_receipts_insert on public.outbox_receipts for insert to authenticated with check (actor_user_id=(select auth.uid()));
create policy audit_events_insert on public.audit_events for insert to authenticated with check (actor_user_id=(select auth.uid()));;
